sp_widget.client_script:
function widgetcontroller($scope, $timeout, $rootScope, $document, $window) {
  var c = this;
  c.loading = false;
  c.tableSearch = '';
  c.filteredList = [];
  c.limit = 15;
  c.page = 0;

  // Cached Counts for HTML (prevents AngularJS digest loop lag)
  c.counts = { total: 0, overdue: 0, review15: 0, review30: 0, highRisk: 0, highGrowth: 0, pending: 0, sendBack: 0, rejected: 0, expiring: 0 };

  c.filters = { segments: [], zones: [], regions: [], depots: [], period: 'latest' };

  function handleClickOutside(event) {
    var target = event.target;
    if (target.closest('.clm-multiselect-container')) return;
    $timeout(function() {
      c.segmentDropdownOpen = false;
      c.zoneDropdownOpen = false;
      c.regionDropdownOpen = false;
      c.depotDropdownOpen = false;
    });
  }
  $document.on('click', handleClickOutside);
  $scope.$on('$destroy', function() { $document.off('click', handleClickOutside); });

  /* ===================== SEGMENT ===================== */
  c.segmentDropdownOpen = false;
  c.segmentSearch = '';
  c.selectedSegmentLabels = [];
  c.openSegmentDropdown = function() { c.segmentDropdownOpen = true; c.zoneDropdownOpen = false; c.regionDropdownOpen = false; c.depotDropdownOpen = false; };
  c.closeSegmentDropdown = function() { $timeout(function() { c.segmentDropdownOpen = false; }, 200); };
  function cascadeResetBelowSegment() {
      c.filters.zones = []; c.selectedZoneLabels = []; c.filters.regions = []; c.selectedRegionLabels = [];
      c.filters.depots = []; c.selectedDepotLabels = []; c.zoneSearch = ''; c.regionSearch = ''; c.depotSearch = '';
  }
  c.toggleSegment = function(s) {
      var idx = c.filters.segments.indexOf(s.value);
      if (idx === -1) { c.filters.segments.push(s.value); c.selectedSegmentLabels.push(s.label); } 
      else { c.filters.segments.splice(idx, 1); c.selectedSegmentLabels.splice(idx, 1); }
      cascadeResetBelowSegment(); c.segmentSearch = ''; c.refresh();
  };
  c.selectAllSegments = function() {
      var allSegments = (c.data && c.data.filterOpts && c.data.filterOpts.segments) || [];
      c.filters.segments = allSegments.map(function(s) { return s.value; });
      c.selectedSegmentLabels = allSegments.map(function(s) { return s.label; });
      cascadeResetBelowSegment(); c.segmentSearch = ''; c.refresh();
  };
  c.clearAllSegments = function() { c.filters.segments = []; c.selectedSegmentLabels = []; cascadeResetBelowSegment(); c.segmentSearch = ''; c.refresh(); };
  c.isSegmentSelected = function(s) { return c.filters.segments.indexOf(s.value) !== -1; };
  c.getFilteredSegments = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.segments) || [];
      var term = (c.segmentSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(s) { return String(s.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getSegmentDisplayText = function() {
      if (!c.selectedSegmentLabels || c.selectedSegmentLabels.length === 0) return 'All Segments';
      if (c.selectedSegmentLabels.length === 1) return c.selectedSegmentLabels[0];
      return c.selectedSegmentLabels.length + ' segments selected';
  };

  /* ===================== ZONE ===================== */
  c.zoneDropdownOpen = false;
  c.zoneSearch = '';
  c.selectedZoneLabels = [];
  c.openZoneDropdown = function() { c.zoneDropdownOpen = true; c.segmentDropdownOpen = false; c.regionDropdownOpen = false; c.depotDropdownOpen = false; };
  c.closeZoneDropdown = function() { $timeout(function() { c.zoneDropdownOpen = false; }, 200); };
  c.toggleZone = function(z) {
      var idx = c.filters.zones.indexOf(z.value);
      if (idx === -1) { c.filters.zones.push(z.value); c.selectedZoneLabels.push(z.label); } 
      else { c.filters.zones.splice(idx, 1); c.selectedZoneLabels.splice(idx, 1); }
      c.filters.regions = []; c.selectedRegionLabels = []; c.filters.depots = []; c.selectedDepotLabels = [];
      c.zoneSearch = ''; c.refresh();
  };
  c.selectAllZones = function() {
      var allZones = (c.data && c.data.filterOpts && c.data.filterOpts.zones) || [];
      c.filters.zones = allZones.map(function(z) { return z.value; });
      c.selectedZoneLabels = allZones.map(function(z) { return z.label; });
      c.filters.regions = []; c.selectedRegionLabels = []; c.filters.depots = []; c.selectedDepotLabels = [];
      c.zoneSearch = ''; c.refresh();
  };
  c.clearAllZones = function() {
      c.filters.zones = []; c.selectedZoneLabels = []; c.filters.regions = []; c.selectedRegionLabels = [];
      c.filters.depots = []; c.selectedDepotLabels = []; c.zoneSearch = ''; c.refresh();
  };
  c.isZoneSelected = function(z) { return c.filters.zones.indexOf(z.value) !== -1; };
  c.getFilteredZones = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.zones) || [];
      var term = (c.zoneSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(z) { return String(z.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getZoneDisplayText = function() {
      if (!c.selectedZoneLabels || c.selectedZoneLabels.length === 0) return 'All Zones';
      if (c.selectedZoneLabels.length === 1) return c.selectedZoneLabels[0];
      return c.selectedZoneLabels.length + ' zones selected';
  };

  /* ===================== REGION ===================== */
  c.regionDropdownOpen = false;
  c.regionSearch = '';
  c.selectedRegionLabels = [];
  c.openRegionDropdown = function() { c.regionDropdownOpen = true; c.segmentDropdownOpen = false; c.zoneDropdownOpen = false; c.depotDropdownOpen = false; };
  c.closeRegionDropdown = function() { $timeout(function() { c.regionDropdownOpen = false; }, 200); };
  c.toggleRegion = function(r) {
      var idx = c.filters.regions.indexOf(r.value);
      if (idx === -1) { c.filters.regions.push(r.value); c.selectedRegionLabels.push(r.label); } 
      else { c.filters.regions.splice(idx, 1); c.selectedRegionLabels.splice(idx, 1); }
      c.filters.depots = []; c.selectedDepotLabels = []; c.regionSearch = ''; c.refresh();
  };
  c.selectAllRegions = function() {
      var allRegions = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      c.filters.regions = allRegions.map(function(r) { return r.value; });
      c.selectedRegionLabels = allRegions.map(function(r) { return r.label; });
      c.filters.depots = []; c.selectedDepotLabels = []; c.regionSearch = ''; c.refresh();
  };
  c.clearAllRegions = function() {
      c.filters.regions = []; c.selectedRegionLabels = []; c.filters.depots = []; c.selectedDepotLabels = [];
      c.regionSearch = ''; c.refresh();
  };
  c.isRegionSelected = function(r) { return c.filters.regions.indexOf(r.value) !== -1; };
  c.getFilteredRegions = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      var term = (c.regionSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(r) { return String(r.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getRegionDisplayText = function() {
      if (!c.selectedRegionLabels || c.selectedRegionLabels.length === 0) return 'All Regions';
      if (c.selectedRegionLabels.length === 1) return c.selectedRegionLabels[0];
      return c.selectedRegionLabels.length + ' regions selected';
  };

  /* ===================== DEPOT ===================== */
  c.depotDropdownOpen = false;
  c.depotSearch = '';
  c.selectedDepotLabels = [];
  c.openDepotDropdown = function() { c.depotDropdownOpen = true; c.segmentDropdownOpen = false; c.zoneDropdownOpen = false; c.regionDropdownOpen = false; };
  c.closeDepotDropdown = function() { $timeout(function() { c.depotDropdownOpen = false; }, 200); };
  c.toggleDepot = function(d) {
      var idx = c.filters.depots.indexOf(d.value);
      if (idx === -1) { c.filters.depots.push(d.value); c.selectedDepotLabels.push(d.label); } 
      else { c.filters.depots.splice(idx, 1); c.selectedDepotLabels.splice(idx, 1); }
      c.depotSearch = ''; c.refresh();
  };
  c.selectAllDepots = function() {
      var allDepots = (c.data && c.data.filterOpts && c.data.filterOpts.depots) || [];
      c.filters.depots = allDepots.map(function(d) { return d.value; });
      c.selectedDepotLabels = allDepots.map(function(d) { return d.label; });
      c.depotSearch = ''; c.refresh();
  };
  c.clearAllDepots = function() { c.filters.depots = []; c.selectedDepotLabels = []; c.depotSearch = ''; c.refresh(); };
  c.isDepotSelected = function(d) { return c.filters.depots.indexOf(d.value) !== -1; };
  c.getFilteredDepots = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.depots) || [];
      var term = (c.depotSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(d) { return String(d.label || '').toLowerCase().indexOf(term) !== -1; });
  };
  c.getDepotDisplayText = function() {
      if (!c.selectedDepotLabels || c.selectedDepotLabels.length === 0) return 'All Depots';
      if (c.selectedDepotLabels.length === 1) return c.selectedDepotLabels[0];
      return c.selectedDepotLabels.length + ' depots selected';
  };

  /* ===================== QUICK FILTERS ===================== */
  c.quickFilter = 'all';
  c.riskFilter = '';
  c.kpiFilter = '';
  c.largeExposureSortOrder = 'desc';

  c.setQuickFilter = function(f) {
      c.quickFilter = f;
      c.page = 0;
      if (f === 'largeExposure') c.largeExposureSortOrder = 'desc';
      c.applyLocalFilters();
  };

  c.setKpiFilter = function(filterName) {
      c.kpiFilter = (c.kpiFilter === filterName) ? '' : filterName;
      c.page = 0;
      c.applyLocalFilters();
      $timeout(function() {
          var el = document.getElementById('clmTableContainer');
          if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
      }, 100);
  };

  c.setRiskKpiFilter = function() {
      c.riskFilter = (c.riskFilter === 'High') ? '' : 'High';
      c.page = 0;
      c.applyLocalFilters();
      $timeout(function() {
          var el = document.getElementById('clmTableContainer');
          if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
      }, 100);
  };

  c.toggleLargeExposureSort = function() {
      c.largeExposureSortOrder = c.largeExposureSortOrder === 'desc' ? 'asc' : 'desc';
      if (c.quickFilter === 'largeExposure') { c.page = 0; c.applyLocalFilters(); }
  };

  c.getLargeExposureIcon = function() { return c.largeExposureSortOrder === 'desc' ? 'fa-sort-amount-desc' : 'fa-sort-amount-asc'; };

  c.isOverdue = function(row) { return !!(row.od90 || 0) && Number(row.od90) > 0; };
  c.getReviewDays = function(row) { var parsed = parseInt(row.reviewIn, 10); return isNaN(parsed) ? null : parsed; };
  c.isReviewWithin = function(row, days) { var d = c.getReviewDays(row); return d !== null && d >= 0 && d <= days; };

  /* ===================== FAST LOCAL FILTERING ===================== */
  c.applyLocalFilters = function() {
      var rows = c.data.tableData || [];

      if (c.selectedHeatRegion) {
          rows = rows.filter(function(r) { return r.region === c.selectedHeatRegion || r.regionName === c.selectedHeatRegion; });
      }

      if (c.kpiFilter) {
          rows = rows.filter(function(row) {
              var s = (row.status || '').toLowerCase();
              if (c.kpiFilter === 'Pending' && s.indexOf('pend') === -1 && s.indexOf('submit') === -1) return false;
              if (c.kpiFilter === 'Send-back' && s.indexOf('send') === -1 && s.indexOf('back') === -1) return false;
              if (c.kpiFilter === 'Rejected' && s.indexOf('reject') === -1) return false;
              return true;
          });
      }

      if (c.riskFilter) {
          rows = rows.filter(function(row) { return row.risk === c.riskFilter; });
      }

      var q = (c.tableSearch || '').toLowerCase().trim();
      if (q) {
          rows = rows.filter(function(row) {
              return (row.code || '').toLowerCase().indexOf(q) > -1 ||
                     (row.name || '').toLowerCase().indexOf(q) > -1 ||
                     (row.pan  || '').toLowerCase().indexOf(q) > -1 ||
                     (row.region || '').toLowerCase().indexOf(q) > -1 ||
                     (row.regionName || '').toLowerCase().indexOf(q) > -1 ||
                     (row.depot  || '').toLowerCase().indexOf(q) > -1;
          });
      }

      if (c.quickFilter === 'largeExposure') {
          rows = rows.filter(function(row) { return (row.od90 || 0) > 0; });
          rows.sort(function(a, b) {
              var diff = (b.od90 || 0) - (a.od90 || 0);
              return c.largeExposureSortOrder === 'desc' ? diff : -diff;
          });
          rows = rows.slice(0, 20);
      } else if (c.quickFilter === 'highGrowth20') {
          rows = rows.filter(function(row) { return row.highGrowth20 === 'Yes'; });
          rows.sort(function(a, b) { return (b.avgMonthlySales || 0) - (a.avgMonthlySales || 0); });
          rows = rows.slice(0, 20);
      } else {
          if (c.quickFilter === 'overdue') rows = rows.filter(c.isOverdue);
          else if (c.quickFilter === 'review15') rows = rows.filter(function(row) { return c.isReviewWithin(row, 15); });
          else if (c.quickFilter === 'review30') rows = rows.filter(function(row) { return c.isReviewWithin(row, 30); });

          rows.sort(function(a, b) { return (b.outstanding || 0) - (a.outstanding || 0); });
      }

      c.filteredList = rows;
      c.updatePagination();
  };

  /* ===================== CACHED COUNTS ===================== */
  function updateCounts() {
      var base = c.data.tableData || [];
      c.counts.total = base.length;
      c.counts.overdue = 0; c.counts.review15 = 0; c.counts.review30 = 0; 
      c.counts.highRisk = 0; c.counts.highGrowth = 0;
      c.counts.pending = 0; c.counts.sendBack = 0; c.counts.rejected = 0; c.counts.expiring = 0;

      for (var i = 0; i < base.length; i++) {
          var r = base[i];
          if (c.isOverdue(r)) c.counts.overdue++;
          if (c.isReviewWithin(r, 15)) c.counts.review15++;
          if (c.isReviewWithin(r, 30)) c.counts.review30++;
          if (r.risk === 'High') c.counts.highRisk++;
          if (r.highGrowth20 === 'Yes') c.counts.highGrowth++;
          if (r.status === 'Pending') c.counts.pending++;
          if (r.status === 'Send-back') c.counts.sendBack++;
          if (r.status === 'Rejected') c.counts.rejected++;
          if (r.reviewIn && parseInt(r.reviewIn) <= 15) c.counts.expiring++;
      }
  }

  /* ===================== CHART 1: Total Outstanding MoM Trend (SVG) ===================== */
  c.trendChart = { points: [], activePoints: [], yTicks: [], linePoints: '', areaPath: '', width: 1200, height: 260, padLeft: 90, padRight: 60, padY: 25, drawHeight: 200, baselineY: 225 };

  c.buildTrendChart = function() {
      var trend = (c.data && c.data.trend && c.data.trend.points) || [];
      if (!trend.length) {
          c.trendChart = { points: [], activePoints: [], yTicks: [], linePoints: '', areaPath: '', width: 1200, height: 260, padLeft: 90, padRight: 60, padY: 25, drawHeight: 200, baselineY: 225 };
          return;
      }
      var width = 1200, height = 260, padLeft = 90, padRight = 60, padY = 25, padBottom = 35;
      var drawHeight = height - padY - padBottom;
      var baselineY = padY + drawHeight;
      var values = trend.map(function(p) { return p.value || 0; });
      var maxVal = Math.max.apply(null, values.concat([0]));
      var minVal = 0;
      if (maxVal <= 0) { maxVal = 1; }
      maxVal = maxVal * 1.1;
      var n = trend.length;
      var stepX = (width - padLeft - padRight) / (n > 1 ? (n - 1) : 1);
      var pts = trend.map(function(p, i) {
          var plotValue = Math.max(0, p.value || 0);
          var x = padLeft + i * stepX;
          var y = padY + (1 - (plotValue - minVal) / (maxVal - minVal)) * drawHeight;
          return { x: x, y: y, label: p.label, value: p.value || 0 };
      });
      var activePts = pts.slice();
      var yTicks = [];
      var tickCount = 4;
      for (var j = 0; j < tickCount; j++) {
          var tickVal = minVal + (maxVal - minVal) * (j / (tickCount - 1));
          var tickY = padY + (1 - (tickVal - minVal) / (maxVal - minVal)) * drawHeight;
          yTicks.push({ y: tickY, label: c.fmtCurrency(tickVal) });
      }
      var linePoints = activePts.map(function(p) { return p.x + ',' + p.y; }).join(' ');
      var areaPath = 'M ' + activePts[0].x + ',' + baselineY + ' ';
      activePts.forEach(function(p) { areaPath += 'L ' + p.x + ',' + p.y + ' '; });
      areaPath += 'L ' + activePts[activePts.length - 1].x + ',' + baselineY + ' Z';
      c.trendChart = {
          points: pts, activePoints: activePts, yTicks: yTicks, linePoints: linePoints, areaPath: areaPath,
          width: width, height: height, padLeft: padLeft, padRight: padRight, padY: padY, drawHeight: drawHeight, baselineY: baselineY
      };
  };

  /* ===================== CHART.JS SETUP ===================== */
  var CHART_JS_URL = 'https://cdn.jsdelivr.net/npm/chart.js@2.9.4/dist/Chart.min.js'; 

  function ensureChartJs(cb) {
      if (typeof Chart !== 'undefined') { cb(); return; }
      if (!window.__clmChartJsPromise) {
          window.__clmChartJsPromise = new Promise(function(resolve, reject) {
              var existing = document.querySelector('script[data-clm-chartjs]');
              if (existing) {
                  existing.addEventListener('load', resolve);
                  existing.addEventListener('error', reject);
                  return;
              }
              var script = document.createElement('script');
              script.src = CHART_JS_URL;
              script.setAttribute('data-clm-chartjs', 'true');
              script.onload = resolve;
              script.onerror = reject;
              document.head.appendChild(script);
          });
      }
      window.__clmChartJsPromise.then(function() { $timeout(cb); }).catch(function(err) { console.error('CLM Widget: failed to load Chart.js', err); });
  }

  window.__clmChartVisibilityTargets = window.__clmChartVisibilityTargets || [];
  function isElementVisible(el) {
      if (!el || !document.body.contains(el)) return false;
      var rect = el.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
  }
  function ensureChartVisibilityWatcher() {
      if (window.__clmChartVisibilityWatcher) return;
      window.__clmChartVisibilityWatcher = new MutationObserver(function() {
          window.__clmChartVisibilityTargets.forEach(function(target) {
              var nowVisible = isElementVisible(target.canvas);
              if (nowVisible && !target.wasVisible) {
                  var inst = target.getInstance();
                  if (inst) { inst.resize(); }
              }
              target.wasVisible = nowVisible;
          });
      });
      window.__clmChartVisibilityWatcher.observe(document.body, { attributes: true, subtree: true, attributeFilter: ['class', 'style'] });
  }
  function registerChartVisibilityTarget(canvas, getChartInstance) {
      if (!canvas) return;
      var already = window.__clmChartVisibilityTargets.some(function(t) { return t.canvas === canvas; });
      if (!already) {
          window.__clmChartVisibilityTargets.push({ canvas: canvas, getInstance: getChartInstance, wasVisible: isElementVisible(canvas) });
      }
      ensureChartVisibilityWatcher();
  }

  var AGEING_COLORS = [
    { key: '0-30 Days',    color: '#38a169' }, { key: '31-60 Days',   color: '#f6e05e' },
    { key: '61-90 Days',   color: '#f6ad55' }, { key: '91-120 Days',  color: '#ed7d31' },
    { key: '121-180 Days', color: '#dd6b20' }, { key: '>180 Days',    color: '#e53e3e' }
  ];

  var salesChartInstance = null;
  var ageingChartInstance = null;
  c.ageingLegend = [];

  c.renderCharts = function() {
    ensureChartJs(function() { renderSalesChart(); renderAgeingChart(); });
  };

  function renderSalesChart() {
      var canvas = document.getElementById('portfolioSalesChart');
      if (!canvas || !c.data.salesTrend || !c.data.salesTrend.points || !c.data.salesTrend.points.length) return;
      var labels = c.data.salesTrend.points.map(function(p) { return p.label || ''; });
      var volumes = c.data.salesTrend.points.map(function(p) { return p.volume || 0; });
      var values  = c.data.salesTrend.points.map(function(p) { return p.value || 0; });
      if (salesChartInstance) { try { salesChartInstance.destroy(); } catch(e) {} }
      salesChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar',
          data: {
              labels: labels,
              datasets: [
                  { type: 'line', label: 'Credit Sales Value (₹)', data: values, borderColor: '#ed7d31', backgroundColor: '#ed7d31', pointBackgroundColor: '#fff', pointBorderColor: '#ed7d31', pointBorderWidth: 2, pointRadius: 5, borderWidth: 3, lineTension: 0, fill: false, spanGaps: false, yAxisID: 'yValue' },
                  { type: 'bar', label: 'Credit Sales Volume (MT)', data: volumes, backgroundColor: '#4472c4', yAxisID: 'yVolume' }
              ]
          },
          options: {
              responsive: true, maintainAspectRatio: false, legend: { display: false }, 
              scales: {
                  xAxes: [{ gridLines: { display: false }, ticks: { fontSize: 11, fontColor: '#64748b' } }],
                  yAxes: [
                      { id: 'yVolume', type: 'linear', position: 'left', scaleLabel: { display: true, labelString: 'Credit Sales Volume (MT)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { color: '#e2e8f0' } },
                      { id: 'yValue', type: 'linear', position: 'right', scaleLabel: { display: true, labelString: 'Credit Sales Value (₹)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { drawOnChartArea: false } }
                  ]
              }
          }
      });
      registerChartVisibilityTarget(canvas, function() { return salesChartInstance; });
  }

  function renderAgeingChart() {
      var canvas = document.getElementById('portfolioAgeingChart');
      if (!canvas || !c.data.ageingTrend || !c.data.ageingTrend.months || !c.data.ageingTrend.months.length) return;
      var months = c.data.ageingTrend.months;
      var labels = months.map(function(m) { return m.label || ''; });
      var datasets = AGEING_COLORS.map(function(bucketDef) {
          return { label: bucketDef.key, backgroundColor: bucketDef.color, data: months.map(function(m) { var match = m.buckets.filter(function(b) { return b.label === bucketDef.key; })[0]; return match ? (match.value || 0) : 0; }) };
      });
      c.ageingLegend = AGEING_COLORS.map(function(b) { return { label: b.key, color: b.color }; });
      if (ageingChartInstance) { try { ageingChartInstance.destroy(); } catch(e) {} }
      ageingChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar', data: { labels: labels, datasets: datasets },
          options: {
              responsive: true, maintainAspectRatio: false, legend: { display: false }, 
              scales: {
                  xAxes: [{ stacked: true, gridLines: { display: false }, ticks: { fontSize: 11, fontColor: '#64748b' } }],
                  yAxes: [{ stacked: true, scaleLabel: { display: true, labelString: 'Outstanding Amount (₹)', fontColor: '#4a5568', fontStyle: 'bold' }, ticks: { fontColor: '#718096' }, gridLines: { color: '#e2e8f0' } }]
              }
          }
      });
      registerChartVisibilityTarget(canvas, function() { return ageingChartInstance; });
  }

  angular.element($window).on('resize', function() {
    if (salesChartInstance) { salesChartInstance.resize(); }
    if (ageingChartInstance) { ageingChartInstance.resize(); }
  });

  $scope.$on('$destroy', function() {
      angular.element($window).off('resize');
      if (salesChartInstance) { try{salesChartInstance.destroy();}catch(e){} }
      if (ageingChartInstance) { try{ageingChartInstance.destroy();}catch(e){} }
  });

  /* ===================== RISK MATRIX ===================== */
  c.heatState = { segment: '', zone: '' };
  c.selectedHeatRegion = null;
  c.riskMatrixLevel = 'segment';
  c.riskMatrixData = [];
  c.riskMatrixMax = 0;

  c.buildRiskMatrix = function() {
      var rows = (c.data && c.data.tableData) || [];
      var level, keyFn;

      if (!c.heatState.segment) {
          level = 'segment'; keyFn = function(r) { return r.segment; };
      } else if (!c.heatState.zone) {
          level = 'zone'; rows = rows.filter(function(r) { return r.segment === c.heatState.segment; }); keyFn = function(r) { return r.zoneName; };
      } else {
          level = 'region'; rows = rows.filter(function(r) { return r.segment === c.heatState.segment && r.zoneName === c.heatState.zone; }); keyFn = function(r) { return r.regionName; };
      }

      var map = {};
      rows.forEach(function(row) {
          var key = keyFn(row) || '(Unassigned)';
          if (!map[key]) { map[key] = { label: key, totalOutstanding: 0, totalOd90: 0, customerCount: 0, highRiskCount: 0, mediumRiskCount: 0, lowRiskCount: 0 }; }
          map[key].totalOutstanding += row.outstanding || 0;
          map[key].totalOd90 += row.od90 || 0;
          map[key].customerCount++;
          if (row.risk === 'High') map[key].highRiskCount++;
          else if (row.risk === 'Medium') map[key].mediumRiskCount++;
          else if (row.risk === 'Low') map[key].lowRiskCount++;
      });
      c.riskMatrixLevel = level;
      c.riskMatrixData = Object.keys(map).map(function(k) { return map[k]; }).sort(function(a, b) { return b.totalOd90 - a.totalOd90; });
      c.riskMatrixMax = c.riskMatrixData.length > 0 ? c.riskMatrixData[0].totalOd90 : 1;
  };

  c.drillMatrix = function(item) {
      if (c.riskMatrixLevel === 'segment') { c.heatState.segment = item.label; } 
      else if (c.riskMatrixLevel === 'zone') { c.heatState.zone = item.label; } 
      else {
          if (c.selectedHeatRegion === item.label) { c.selectedHeatRegion = null; } 
          else { c.selectedHeatRegion = item.label; }
          c.page = 0; c.applyLocalFilters();
          $timeout(function() { var el = document.getElementById('clmTableContainer'); if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }, 50);
          return;
      }
      c.buildRiskMatrix();
  };

  c.resetHeatToSegments = function() { c.heatState.segment = ''; c.heatState.zone = ''; c.selectedHeatRegion = null; c.applyLocalFilters(); c.buildRiskMatrix(); };
  c.resetHeatToZones = function() { c.heatState.zone = ''; c.selectedHeatRegion = null; c.applyLocalFilters(); c.buildRiskMatrix(); };
  c.clearHeatDrilldown = function() { c.selectedHeatRegion = null; c.page = 0; c.applyLocalFilters(); };

  var HEAT_RED = '#e53e3e'; var HEAT_ORANGE = '#f6ad55'; var HEAT_YELLOW = '#f6e05e'; var HEAT_GREEN = '#c6f6d5';
  c.getHeatColor = function(item) {
      var highCount = (item && item.highRiskCount) || 0;
      if (highCount >= 100) return HEAT_RED;
      if (highCount >= 10) return HEAT_ORANGE;
      if (highCount >= 1) return HEAT_YELLOW;
      return HEAT_GREEN;
  };
  c.getHeatTextColor = function(item) { var color = c.getHeatColor(item); return (color === HEAT_RED || color === HEAT_ORANGE) ? '#fff' : '#1f2933'; };

  c.regionTooltip = { show: false, x: 0, y: 0, data: null };
  c.showRegionTooltip = function(event, item) {
      c.regionTooltip.data = item;
      var container = event.currentTarget.closest('.clm-heatmap-container');
      if (!container) return;
      var containerRect = container.getBoundingClientRect();
      var targetRect = event.currentTarget.getBoundingClientRect();
      var left = targetRect.right - containerRect.left + 14;
      var top = targetRect.top - containerRect.top;
      if (left + 220 > containerRect.width) { left = targetRect.left - containerRect.left - 220; }
      if (top + 140 > containerRect.height) { top = targetRect.bottom - containerRect.top - 140; }
      c.regionTooltip.x = left; c.regionTooltip.y = top; c.regionTooltip.show = true;
      $scope.$applyAsync();
  };
  c.hideRegionTooltip = function() { c.regionTooltip.show = false; $scope.$applyAsync(); };

  /* ===================== ACTIVE FILTER COUNT / CLEAR ALL ===================== */
  c.getActiveFilterCount = function() {
      var count = 0;
      if (c.filters.segments && c.filters.segments.length > 0) count++;
      if (c.filters.zones && c.filters.zones.length > 0) count++;
      if (c.filters.regions && c.filters.regions.length > 0) count++;
      if (c.filters.depots && c.filters.depots.length > 0) count++;
      if (c.filters.period && c.filters.period !== 'latest') count++;
      if (c.riskFilter) count++;
      if (c.kpiFilter) count++;
      if (c.quickFilter !== 'all') count++;
      if (c.selectedHeatRegion) count++;
      return count;
  };

  c.filterWrapperClass = '';

  c.clearAllFilters = function() {
      c.filterWrapperClass = 'collapsing';
      $timeout(function() {
          c.filters.segments = []; c.selectedSegmentLabels = []; c.segmentSearch = '';
          c.filters.zones = []; c.selectedZoneLabels = []; c.zoneSearch = '';
          c.filters.regions = []; c.selectedRegionLabels = []; c.regionSearch = '';
          c.filters.depots = []; c.selectedDepotLabels = []; c.depotSearch = '';
          c.filters.period = 'latest'; c.riskFilter = ''; c.kpiFilter = ''; c.quickFilter = 'all'; c.tableSearch = '';
          c.selectedHeatRegion = null; c.page = 0;
          c.filterWrapperClass = '';
          c.refresh();
      }, 350);
  };

  // ========== LOCAL PERIOD LOGIC ==========
  var allTimeTableData = [];

  function getPeriodBounds(period) {
      var now = new Date();
      var start = null, end = new Date();
      if (period === 'this_month') { start = new Date(now.getFullYear(), now.getMonth(), 1); } 
      else if (period === 'last_month') { start = new Date(now.getFullYear(), now.getMonth() - 1, 1); end = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59); } 
      else if (period === 'this_year') { start = new Date(now.getFullYear(), 0, 1); } 
      else if (period === 'last_year') { start = new Date(now.getFullYear() - 1, 0, 1); end = new Date(now.getFullYear() - 1, 11, 31, 23, 59, 59); }
      return { start: start, end: end };
  }

  function filterRowsByPeriod(rows, period) {
      if (period === 'latest') return rows;
      var bounds = getPeriodBounds(period);
      if (!bounds.start) return rows;
      return rows.filter(function(row) {
          var d = row.createdOn;
          if (!d) return false;
          var rd = new Date(d.substring(0,10));
          return rd >= bounds.start && rd <= bounds.end;
      });
  }

  function recalcKpisFromRows(rows) {
      var count = rows.length;
      var limit = 0, outstanding = 0, available = 0, utilPct = 0;
      var overdueExp = 0, od90 = 0, grossExp = 0;
      var totalActiveSd = 0, totalOsSales = 0;

      rows.forEach(function(r) {
          limit += (r.limit || 0); 
          outstanding += (r.outstanding || 0);
          overdueExp += (r.overdueTotal || 0);
          od90 += (r.od90 || 0);
          grossExp += (r.grossExp || 0);
          totalActiveSd += (r.activeSd || 0);
          totalOsSales += (r.osSalesRatio || 0);
      });

      available = limit - outstanding;
      utilPct = limit > 0 ? Math.round((outstanding / limit) * 100) : 0;

      var hhiSum = 0;
      if (outstanding > 0) {
          rows.forEach(function(r) {
              var share = (r.outstanding || 0) / outstanding * 100;
              hhiSum += share * share;
          });
      }
      var concentrationRisk = Math.round(hhiSum);
      var concentrationLabel = 'Less';
      if (concentrationRisk > 2500) concentrationLabel = 'High';
      else if (concentrationRisk >= 1500) concentrationLabel = 'Moderate';

      var netExposure = outstanding - totalActiveSd;

      return {
          customerCount: count, limit: limit, outstanding: outstanding, available: available, utilPct: utilPct,
          overdueExposure: overdueExp, od90: od90, grossExposure: grossExp,
          concentrationRisk: concentrationRisk, concentrationLabel: concentrationLabel,
          netExposure: netExposure, osSalesRatioSum: totalOsSales
      };
  }

  c.onPeriodChange = function() {
      if (!allTimeTableData.length) return;
      var filtered = filterRowsByPeriod(allTimeTableData, c.filters.period);
      c.data.tableData = filtered;
      c.data.kpis = recalcKpisFromRows(filtered);
      updateCounts();
      c.buildRegionRiskChart();
      c.applyLocalFilters();
  };

  function onServerData(data) {
      allTimeTableData = data.tableData.slice();
      var filtered = filterRowsByPeriod(allTimeTableData, c.filters.period);
      c.data.tableData = filtered;
      c.data.kpis = recalcKpisFromRows(filtered);
      updateCounts();
      c.buildTrendChart();
      c.renderCharts();
      c.buildRiskMatrix();
      c.applyLocalFilters();
  }

  c.refresh = function() {
      c.loading = true;
      c.page = 0;
      var payload = { filters: angular.copy(c.filters) };
      if (c.data && c.data.filterOpts) payload.filterOpts = c.data.filterOpts;
      c.server.get(payload).then(function(r) {
          c.data = r.data;
          onServerData(c.data);
          c.loading = false;
      });
  };

  c.updatePagination = function() { c.page = 0; };
  c.getPageArray = function() {
      if (!c.filteredList) return [0];
      var totalPages = Math.ceil(c.filteredList.length / c.limit);
      if (totalPages === 0) return [0];
      var maxPage = totalPages - 1;
      var start = Math.max(0, c.page - 2);
      var end = Math.min(maxPage, c.page + 2);
      var arr = [];
      for (var i = start; i <= end; i++) { arr.push(i); }
      return arr;
  };

  c.fmtCurrency = function(value) {
      if (value === undefined || value === null || isNaN(value)) return '—';
      var abs = Math.abs(value);
      var sign = value < 0 ? '-' : '';
      if (abs === 0) return '₹0.0L';
      if (abs >= 1e7) return sign + '₹' + (abs / 1e7).toFixed(1) + ' Cr';
      return sign + '₹' + (abs / 1e5).toFixed(1) + 'L';
  };
  c.fmtDash = function(val) { if (!val || isNaN(val) || val === 0) return '—'; return c.fmtCurrency(val); };
  c.fmtRatio = function(value) { if (value === undefined || value === null || isNaN(value)) return '—'; return Number(value).toFixed(2); };
  c.capPct = function(pct) { if (pct === undefined || pct === null || isNaN(pct)) return 0; return Math.max(0, Math.min(100, pct)); };
  c.selectCustomer = function(row) {
      if (!row || !row.code) return;
      $rootScope.clmPendingCustomerSysId = row.sysId || null;
      $rootScope.clmPendingCustomerCode = row.code;
      $rootScope.$broadcast('clm.customer.selected', { sysId: row.sysId || null, code: row.code });
      $rootScope.$broadcast('clm.switch.tab', 'customer360');
  };

  c.refresh();
}

sp_widget.css:
/* =============================================
   COMPLETE CLM PORTFOLIO OVERVIEW CSS
   (full‑page branded background, compact layout, filter fix)
   ============================================= */

/* ---------- Base & Background ---------- */
.clm-portfolio-overview {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background: #f1f5f9;
  color: #1e293b;
  padding: 16px 16px 24px 16px;
  min-height: 100vh;
  position: relative;
  overflow: hidden;
}

/* ---- Subtle corporate background (cement texture + full‑page logo watermark) ---- */
.clm-portfolio-overview::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;

  background-image:
    /* layer 1: diagonal grid pattern */
    repeating-linear-gradient(
      45deg,
      transparent,
      transparent 10px,
      rgba(200,200,200,0.03) 10px,
      rgba(200,200,200,0.03) 11px
    ),
    /* layer 2: opposite diagonal grid pattern */
    repeating-linear-gradient(
      -45deg,
      transparent,
      transparent 10px,
      rgba(200,200,200,0.03) 10px,
      rgba(200,200,200,0.03) 11px
    ),
    /* layer 3: your provided image (now covering the entire viewport) */
    url('https://images.jdmagicbox.com/v2/comp/mangalore/e7/0824px824.x824.110203102819.h9e7/catalogue/ultra-tech-cement-ltd-kodialbail-mangalore-cement-dealers-ultratech-b6fbdahk4k.jpg');

  background-repeat: repeat, repeat, no-repeat;
  background-position: 0 0, 0 0, center;
  background-size: auto, auto, cover;   /* image covers the whole background */

  opacity: 0.05;                         /* very faint, won't distract */
  filter: grayscale(100%);
}

/* All content above the background */
.clm-filter-card,
.clm-section-title,
.clm-kpi-grid,
.clm-chart-card,
.clm-table-container {
  position: relative;
  z-index: 1;
}

/* ---------- Section Titles ---------- */
.clm-section-title {
  font-size: 14px;
  font-weight: 700;
  color: #334155;
  margin: 20px 0 10px 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 6px;
  border-bottom: 2px solid #e2e8f0;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.clm-section-title i {
  color: #1c4e9c;
  font-size: 16px;
  background: #e0e7ff;
  padding: 5px;
  border-radius: 6px;
}

/* ---------- Filter Card ---------- */
.clm-filter-card {
  margin: 0 0 16px 0;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 12px 16px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.03);
  position: sticky;
  top: 0;
  z-index: 30;
  backdrop-filter: blur(6px);
  overflow: visible;
}
.clm-filter-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: nowrap;
  white-space: nowrap;
  overflow: visible;
  min-width: fit-content;
}
.clm-filter-field {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #475569;
  font-weight: 600;
  flex: 1;
  min-width: 0;
}
.clm-filter-field select {
  width: 100%;
  min-width: 130px;
  height: 32px;
  font-size: 12px;
  border-radius: 6px;
  border: 1px solid #cbd5e1;
  background: #ffffff;
  padding: 0 10px;
  outline: none;
  cursor: pointer;
  transition: all 0.2s;
}
.clm-filter-field select:hover {
  border-color: #94a3b8;
  background: #f8fafc;
}

/* ---------- Multiselect ---------- */
.clm-multiselect-container {
  position: relative;
  width: 100%;
  min-width: 140px;
}
.clm-multiselect-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 32px;
  padding: 0 10px;
  font-size: 12px;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.clm-multiselect-trigger:hover {
  border-color: #94a3b8;
}
.clm-multiselect-container.open .clm-multiselect-trigger {
  border-color: #1c4e9c;
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  box-shadow: 0 0 0 2px rgba(28,78,156,0.15);
}
.clm-multiselect-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #1e293b;
  flex: 1;
}
.clm-multiselect-arrow {
  color: #64748b;
  font-size: 10px;
  margin-left: 6px;
}
.clm-multiselect-dropdown {
  position: absolute;
  top: 32px;
  left: 0;
  right: 0;
  z-index: 100;
  background: #fff;
  border: 1px solid #1c4e9c;
  border-top: none;
  border-radius: 0 0 8px 8px;
  box-shadow: 0 10px 25px rgba(0,0,0,0.1);
  max-height: 240px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.clm-multiselect-actions {
  display: flex;
  justify-content: space-between;
  padding: 6px 10px;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
}
.clm-multiselect-actions a {
  font-size: 11px;
  color: #1c4e9c;
  cursor: pointer;
  font-weight: 600;
  text-decoration: none;
}
.clm-multiselect-actions a:hover {
  text-decoration: underline;
}
.clm-multiselect-search {
  width: 100%;
  height: 30px;
  padding: 0 10px;
  border: none;
  border-bottom: 1px solid #e2e8f0;
  font-size: 12px;
  outline: none;
}
.clm-multiselect-list {
  list-style: none;
  margin: 0;
  padding: 4px 0;
  overflow-y: auto;
  max-height: 140px;
}
.clm-multiselect-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  font-size: 12px;
  cursor: pointer;
  color: #1e293b;
}
.clm-multiselect-list li:hover {
  background: #f1f5f9;
}
.clm-multiselect-list li.selected {
  background: #e0e7ff;
}
.clm-dropdown-empty {
  color: #94a3b8 !important;
  cursor: default !important;
  font-style: italic;
  padding: 10px 14px;
}
.clm-checkbox {
  width: 14px;
  height: 14px;
  border: 2px solid #cbd5e1;
  border-radius: 3px;
  display: inline-block;
  flex-shrink: 0;
  position: relative;
  background: #fff;
}
.clm-checkbox.checked {
  background: #1c4e9c;
  border-color: #1c4e9c;
}
.clm-checkbox.checked::after {
  content: '';
  position: absolute;
  left: 3px;
  top: 1px;
  width: 4px;
  height: 8px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

/* ---------- KPI Cards (no lift, no top-right icon) ---------- */
.clm-kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
  margin: 12px 0;
  position: relative;
  z-index: 1;
}
.clm-kpi-card {
  background: #ffffff;
  border-radius: 10px;
  padding: 12px 14px;
  box-shadow: 0 1px 6px rgba(0,0,0,0.03);
  border: 1px solid #e2e8f0;
  transition: box-shadow 0.2s ease;
  position: relative;
  overflow: hidden;
}
.clm-kpi-card:hover {
  box-shadow: 0 4px 16px rgba(0,0,0,0.08);
}
.clm-kpi-card.border-blue   { border-left: 4px solid #1c4e9c; }
.clm-kpi-card.border-orange { border-left: 4px solid #dd6b20; }
.clm-kpi-card.border-green  { border-left: 4px solid #38a169; }
.clm-kpi-card.border-teal   { border-left: 4px solid #319795; }
.clm-kpi-card.border-red    { border-left: 4px solid #e53e3e; }
.clm-kpi-card.border-purple { border-left: 4px solid #7c3aed; }

/* KPI icon hidden */
.clm-kpi-icon { display: none; }

.clm-kpi-code {
  font-size: 10px;
  font-weight: 700;
  color: #64748b;
  letter-spacing: 0.3px;
  margin-bottom: 4px;
  text-transform: uppercase;
}
.clm-kpi-value {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 2px;
}
.clm-kpi-value.large { font-size: 24px; }
.clm-kpi-sub {
  font-size: 10px;
  color: #94a3b8;
  font-weight: 500;
}
.clm-progress {
  height: 3px;
  border-radius: 2px;
  background: #e2e8f0;
  margin-top: 8px;
}
.clm-progress-fill {
  height: 100%;
  border-radius: 2px;
}
.bg-blue { background: #1c4e9c; }
.bg-teal { background: #319795; }

.clm-kpi-info {
  position: absolute;
  top: 8px;
  right: 12px;
  color: #64748b;
  font-size: 14px;
  cursor: pointer;
  transition: color 0.2s;
  z-index: 5;
}
.clm-kpi-info:hover { color: #1c4e9c; }

.clickable { cursor: pointer; }

.text-blue   { color: #1c4e9c; }
.text-orange { color: #dd6b20; }
.text-green  { color: #38a169; }
.text-teal   { color: #319795; }
.text-red    { color: #e53e3e; }
.text-purple { color: #7c3aed; }

/* ---------- Charts ---------- */
.clm-chart-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 16px;
  margin: 12px 0;
  box-shadow: 0 1px 6px rgba(0,0,0,0.02);
  overflow: hidden;
  position: relative;
  z-index: 1;
}
.clm-chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
.clm-chart-title {
  font-size: 13px;
  font-weight: 700;
  color: #1e293b;
  display: flex;
  align-items: center;
  gap: 6px;
}
.clm-chart-title i { color: #1c4e9c; }
.clm-chart-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 14px;
  background: #f1f5f9;
  color: #334155;
  letter-spacing: 0.3px;
}
.clm-badge-line    { background: #e6f0ff; color: #1c4e9c; }
.clm-badge-combo   { background: #f3e8ff; color: #6b21a8; }
.clm-badge-stacked { background: #fef3c7; color: #b45309; }
.clm-badge-heatmap {
  background: linear-gradient(135deg, #e53e3e, #dd6b20);
  color: #fff;
  padding: 2px 10px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.clm-chart-empty {
  text-align: center;
  padding: 20px;
  color: #94a3b8;
  font-style: italic;
  font-size: 12px;
}

/* Trend SVG */
.clm-trend-body {
  height: 260px;
  position: relative;
}
.clm-trend-svg {
  width: 100%;
  height: 100%;
  display: block;
}
.clm-trend-area { fill: rgba(221,107,32,0.1); }
.clm-trend-line { fill: none; stroke: #dd6b20; stroke-width: 2px; }
.clm-trend-dot { fill: #fff; stroke: #dd6b20; stroke-width: 2px; cursor: pointer; transition: r 0.2s; }
.clm-trend-dot:hover { r: 6; fill: #dd6b20; }
.clm-trend-dot.last { fill: #dd6b20; }
.clm-trend-grid line { stroke: #e2e8f0; stroke-dasharray: 4; stroke-width: 1px; }
.clm-trend-yaxis text, .clm-trend-xaxis text {
  font-size: 11px;
  fill: #64748b;
  font-family: inherit;
}

.clm-charts-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 12px 0;
}
@media (max-width: 768px) { .clm-charts-row { grid-template-columns: 1fr; } }
.clm-chart-half { margin: 0; }
.clm-ageing-legend {
  display: flex;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 10px;
  padding: 4px 0;
}
.clm-legend-item {
  font-size: 11px;
  color: #334155;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 6px;
}
.clm-legend-color {
  width: 12px;
  height: 12px;
  border-radius: 2px;
  display: inline-block;
}

/* Heatmap */
.clm-heatmap-card { }
.clm-heatmap-container { padding: 12px 16px; }
.clm-pie-breadcrumb { font-size: 12px; color: #64748b; margin-bottom: 8px; }
.clm-pie-breadcrumb .crumb { cursor: pointer; padding: 2px 4px; }
.clm-pie-breadcrumb .crumb.active { font-weight: 700; color: #1c4e9c; cursor: default; }
.clm-pie-breadcrumb .crumb:not(.active):hover { text-decoration: underline; }
.clm-heatmap-legend {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid #e2e8f0;
}
.clm-legend-label { font-size: 12px; font-weight: 600; color: #475569; }
.clm-legend-gradient { display: flex; gap: 2px; }
.clm-legend-color { width: 20px; height: 12px; border-radius: 2px; }
.clm-legend-text { font-size: 11px; color: #64748b; }
.clm-heatmap-matrix {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2px;
  border-radius: 10px;
  overflow: hidden;
}
.clm-matrix-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 60px;
  cursor: pointer;
  position: relative;
  transition: outline 0.15s;
}
.clm-matrix-cell:hover {
  outline: 2px solid #1c4e9c;
  outline-offset: -2px;
}
.clm-matrix-cell.selected {
  outline: 3px solid #1c4e9c;
  outline-offset: -3px;
}
.clm-cell-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 6px 4px;
  pointer-events: none;
}
.clm-cell-region {
  font-size: 13px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 3px;
}
.clm-cell-badges { display: flex; gap: 3px; flex-wrap: wrap; justify-content: center; }
.clm-cell-badge {
  padding: 0px 5px;
  border-radius: 10px;
  font-size: 9px;
  font-weight: 700;
  background: rgba(255,255,255,0.85);
  border: 1px solid rgba(0,0,0,0.15);
  line-height: 15px;
}
.clm-badge-h { color: #c53030; }
.clm-badge-m { color: #9c4221; }
.clm-badge-l { color: #276749; }
.clm-heatmap-tooltip {
  position: absolute;
  background: rgba(15,15,15,0.95);
  color: #fff;
  padding: 12px 16px;
  border-radius: 10px;
  font-size: 12px;
  z-index: 1000;
  pointer-events: none;
  box-shadow: 0 8px 20px rgba(0,0,0,0.3);
  min-width: 180px;
  backdrop-filter: blur(4px);
  transition: left 0.1s ease, top 0.1s ease;
}
.clm-tooltip-title {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(255,255,255,0.25);
}
.clm-tooltip-row {
  margin-bottom: 4px;
  font-size: 12px;
  line-height: 1.3;
}

/* ---------- Table Section ---------- */
.clm-table-container {
  margin: 12px 0;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 1px 6px rgba(0,0,0,0.02);
  position: relative;
  z-index: 1;
}
.clm-chip-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  padding: 8px 12px;
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}
.clm-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 30px;
  padding: 0 10px;
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-radius: 15px;
  cursor: pointer;
  transition: all 0.15s;
}
.clm-chip:hover {
  background: #e2e8f0;
  border-color: #94a3b8;
}
.clm-chip.active {
  background: #1c4e9c;
  border-color: #1c4e9c;
  color: #ffffff;
}
.clm-chip .clm-chip-count {
  background: rgba(0,0,0,0.08);
  color: inherit;
  border-radius: 10px;
  padding: 1px 5px;
  font-size: 10px;
}
.clm-chip.active .clm-chip-count {
  background: rgba(255,255,255,0.25);
}
.clm-chip-warn i   { color: #b45309; }
.clm-chip-orange i { color: #dd6b20; }
.clm-chip-blue i   { color: #1c4e9c; }
.clm-chip.active i { color: #ffffff; }
.clm-chip-purple {
  background: #f3e8ff;
  color: #7c3aed;
  border-color: #d8b4fe;
}
.clm-chip-purple:hover,
.clm-chip-purple.active {
  background: #7c3aed;
  color: #fff;
  border-color: #7c3aed;
}
.clm-chip-green {
  background: #e6fffa;
  color: #2c7a7b;
  border-color: #b2f5ea;
}
.clm-chip-green:hover,
.clm-chip-green.active {
  background: #2c7a7b;
  color: #fff;
  border-color: #2c7a7b;
}
.clm-selected-region-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 30px;
  padding: 0 10px;
  font-size: 11px;
  font-weight: 600;
  color: #fff;
  background: #2563eb;
  border-radius: 15px;
}
.clm-selected-region-chip i.fa-times {
  cursor: pointer;
  opacity: 0.8;
  font-size: 10px;
}
.clm-selected-region-chip i.fa-times:hover { opacity: 1; }
.clm-risk-select {
  width: auto;
  display: inline-block;
  height: 30px;
  padding: 0 10px;
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 15px;
  outline: none;
  cursor: pointer;
}
.clm-filters-transition-wrapper {
  max-height: 200px;
  overflow: hidden;
  transition: max-height 0.3s ease, opacity 0.3s ease, padding 0.3s ease;
  opacity: 1;
  padding: 10px 12px;
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}
.clm-filters-transition-wrapper.collapsing {
  max-height: 0;
  opacity: 0;
  padding-top: 0;
  padding-bottom: 0;
  border-bottom: none;
}
.clm-active-filters-inline {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.clm-filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  padding: 3px 10px;
  font-size: 10px;
  font-weight: 600;
  color: #334155;
}
.clm-filter-chip i {
  cursor: pointer;
  color: #94a3b8;
  font-size: 9px;
}
.clm-filter-chip i:hover { color: #e53e3e; }
.clm-clear-all-inline {
  background: none;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 3px 10px;
  font-size: 10px;
  font-weight: 600;
  color: #e53e3e;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: background 0.2s;
}
.clm-clear-all-inline:hover { background: #fff5f5; }

.clm-table-toolbar-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background: #ffffff;
  border-bottom: 1px solid #e2e8f0;
}
.clm-search-box {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  max-width: 280px;
}
.clm-search-box i {
  position: absolute;
  left: 10px;
  color: #94a3b8;
  font-size: 12px;
}
.clm-search-box input {
  width: 100%;
  height: 32px;
  padding: 0 10px 0 28px;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font-size: 12px;
  outline: none;
  background: #ffffff;
  transition: border 0.2s;
}
.clm-search-box input:focus {
  border-color: #1c4e9c;
  box-shadow: 0 0 0 2px rgba(28,78,156,0.1);
}
.clm-table-controls-right {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  color: #475569;
}
.clm-record-count { font-weight: 600; }
.clm-badge-blue {
  background: #e0e7ff;
  color: #1c4e9c;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 700;
}

.clm-table-wrapper {
  max-height: 380px;
  overflow: auto;
  width: 100%;
}
.clm-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: auto;
  font-size: 11px;
}
.clm-table thead th {
  position: sticky;
  top: 0;
  z-index: 10;
  text-align: left;
  padding: 8px 6px;
  background: #f8fafc;
  color: #475569;
  font-weight: 700;
  text-transform: uppercase;
  font-size: 9px;
  letter-spacing: 0.3px;
  border-bottom: 2px solid #cbd5e1;
  white-space: normal !important;
  vertical-align: bottom;
  line-height: 1.2;
}
.clm-table td {
  padding: 6px 6px;
  border-bottom: 1px solid #f1f5f9;
  color: #334155;
  vertical-align: middle;
}
.clm-table tbody tr:hover { background-color: #f8fafc; }
.clm-code {
  color: #1c4e9c;
  font-weight: 600;
  cursor: pointer;
}
.clm-sub-pan {
  display: block;
  font-size: 9px;
  color: #64748b;
  margin-top: 1px;
}
.clm-nowrap { white-space: nowrap !important; }
.clm-strong { font-weight: 600; }
.clm-text-red { color: #e53e3e !important; font-weight: 600; }

.clm-pill-status {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 9px;
  font-weight: 600;
  display: inline-block;
  white-space: nowrap;
}
.status-approved  { background: #e3f4ea; color: #1f7a4d; }
.status-submitted { background: #fffdf0; color: #975a16; }
.status-norequest { background: #f1f5f9; color: #475569; }
.clm-hg-yes { background: #e6fffa; color: #2c7a7b; }
.clm-hg-no  { background: #f8fafc; color: #64748b; }

.seg-cement  { background: #ede9fe; color: #5b21b6; padding: 2px 8px; border-radius: 4px; font-size: 9px; font-weight: 600; }
.seg-bpd     { background: #fffdf0; color: #975a16; }
.seg-default { color: #1e293b; font-weight: 500; }

.clm-mini-progress {
  width: 24px;
  height: 3px;
  background: #e2e8f0;
  border-radius: 2px;
}
.clm-mini-fill {
  height: 100%;
  border-radius: 2px;
  background: currentColor;
}

.clm-table-footer {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding: 8px 12px;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
  position: sticky;
  bottom: 0;
  z-index: 10;
}
.clm-page-numbers { display: flex; gap: 3px; }
.clm-page-btn {
  background: #ffffff;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  height: 28px;
  min-width: 28px;
  cursor: pointer;
  color: #475569;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
}
.clm-page-btn:hover:not(:disabled) { background: #f1f5f9; }
.clm-page-btn.active {
  background: #1c4e9c;
  color: #fff;
  border-color: #1c4e9c;
}
.clm-page-btn:disabled {
  color: #cbd5e1;
  background: #f8fafc;
  cursor: not-allowed;
  border-color: #e2e8f0;
}

.clm-loading {
  text-align: center;
  padding: 30px;
  color: #64748b;
  font-weight: 600;
  font-size: 13px;
}

sp_widget.script:
(function() {
    var TABLES = {
        master:    'x_birl3_clm_clm_customer_master1',
        request:   'x_birl3_clm_clm_new_credit_request',
        snapshot:  'x_birl3_clm_clm_aging_snapshot',
        roleMap:   'x_birl3_clm_role_user_mapping',
        salesData: 'x_birl3_clm_clm_cement_rmc_bpd_values',
        salesVol:  'x_birl3_clm_clm_sales_data'
    };

    var SALES_FIELDS = ['u_jun_25','u_jul_25','u_aug_25','u_sep_25','u_oct_25','u_nov_25',
                         'u_dec_25','u_jan_26','u_feb_26','u_mar_26','u_apr_26','u_may_26'];

    var HIGH_GROWTH_THRESHOLD_PCT = 110;

    var MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    var MONTH_ABBR  = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
    function pad2(n) { return n < 10 ? '0' + n : '' + n; }

    function buildJan26FieldMonths() {
        var out = [];
        var now = new Date();
        var d = new Date(2026, 0, 1);
        var endD = new Date(now.getFullYear(), now.getMonth(), 1);
        while (d <= endD) {
            out.push({ year: d.getFullYear(), month: d.getMonth() });
            d.setMonth(d.getMonth() + 1);
        }
        return out;
    }
    var JAN26_MONTHS = buildJan26FieldMonths();
    var JAN26_SALES_FIELDS = JAN26_MONTHS.map(function(m) {
        return 'u_' + MONTH_ABBR[m.month] + '_' + String(m.year).slice(-2);
    });

    var jan26Start = '2026-01-01 00:00:00';
    var jan26End = (function() {
        var now = new Date();
        var lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
        return now.getFullYear() + '-' + pad2(now.getMonth() + 1) + '-' + pad2(lastDay) + ' 23:59:59';
    })();

    var inputFilters = (input && input.filters) ? input.filters :
        { segments: [], zones: [], regions: [], depots: [], period: 'latest' };

    function normalizeArray(val) {
        if (typeof val === 'string') {
            try { val = JSON.parse(val); }
            catch (e) { val = val ? [val] : []; }
        }
        if (!Array.isArray(val)) { val = val ? [val] : []; }
        return val;
    }
    inputFilters.segments = normalizeArray(inputFilters.segments);
    inputFilters.zones = normalizeArray(inputFilters.zones);
    inputFilters.regions = normalizeArray(inputFilters.regions);
    inputFilters.depots = normalizeArray(inputFilters.depots);

    var gdtToday = new GlideDateTime();
    var currentUserId = gs.getUserID();

    // ==============================
    // ROLE CHECK (CFO)
    // ==============================
    var isCFO = false;
    var grRole = new GlideRecord(TABLES.roleMap);
    grRole.addQuery('u_user', currentUserId);
    grRole.addQuery('u_role', 'CFO');
    grRole.query();
    if (grRole.next()) { isCFO = true; }

    if (!isCFO) {
        data.error = 'User is not mapped as CFO';
        data.accessDenied = true;
        data.filterOpts = { segments: [], zones: [], regions: [], depots: [], periods: [] };
        data.kpis = {};
        data.tableData = [];
        data.trend = { points: [] };
        data.salesTrend = { points: [] };
        data.ageingTrend = { months: [] };
        return;
    }

    data.isCFO = isCFO;
    data.accessDenied = false;

    function buildCodeNameMap(codeField, nameField, scopeFilters) {
        var ga = new GlideAggregate(TABLES.master);
        if (scopeFilters.segments && scopeFilters.segments.length > 0) ga.addQuery('segment', 'IN', scopeFilters.segments);
        if (scopeFilters.zones && scopeFilters.zones.length > 0) ga.addQuery('zone', 'IN', scopeFilters.zones);
        if (scopeFilters.regions && scopeFilters.regions.length > 0) ga.addQuery('region', 'IN', scopeFilters.regions);
        ga.groupBy(codeField);
        ga.groupBy(nameField);
        ga.query();
        var map = {};
        while (ga.next()) {
            var code = ga.getValue(codeField);
            if (!code) continue;
            if (!map[code]) { var nm = ga.getValue(nameField); map[code] = nm || code; }
        }
        var arr = [];
        for (var k in map) { arr.push({ value: k, label: map[k] }); }
        arr.sort(function(a, b) { return String(a.label).localeCompare(String(b.label)); });
        return arr;
    }

    function getDistinctSegments() {
        var arr = [];
        var ga = new GlideAggregate(TABLES.master);
        ga.addAggregate('GROUP_BY', 'segment');
        ga.query();
        while (ga.next()) {
            var val = ga.getDisplayValue('segment');
            if (val && arr.indexOf(val) === -1) arr.push(val);
        }
        arr.sort();
        return arr.map(function(s) { return { value: s, label: s }; });
    }

    data.filterOpts = {
        segments: getDistinctSegments(),
        zones:    buildCodeNameMap('zone', 'zone_name', { segments: inputFilters.segments }),
        regions:  buildCodeNameMap('region', 'region_name', { segments: inputFilters.segments, zones: inputFilters.zones }),
        depots:   buildCodeNameMap('depot', 'depot_name', { segments: inputFilters.segments, zones: inputFilters.zones, regions: inputFilters.regions }),
        periods: [
            { label: 'All Time (Latest)', value: 'latest' },
            { label: 'This Month', value: 'this_month' },
            { label: 'Last Month', value: 'last_month' },
            { label: 'This Year', value: 'this_year' },
            { label: 'Last Year', value: 'last_year' }
        ]
    };

    function chunkArray(myArray, chunk_size) {
        var results = [];
        var copy = myArray.slice();
        while (copy.length) { results.push(copy.splice(0, chunk_size)); }
        return results;
    }

    var masterRecords = [];
    var sysIdArray = [];
    var reqMap = {};
    var snapMap = {};
    var salesMap = {};
    var outstandingSumMap = {};

    var grCust = new GlideRecord(TABLES.master);
    if (inputFilters.segments && inputFilters.segments.length > 0) grCust.addQuery('segment', 'IN', inputFilters.segments);
    if (inputFilters.zones && inputFilters.zones.length > 0) grCust.addQuery('zone', 'IN', inputFilters.zones);
    if (inputFilters.regions && inputFilters.regions.length > 0) grCust.addQuery('region', 'IN', inputFilters.regions);
    if (inputFilters.depots && inputFilters.depots.length > 0) grCust.addQuery('depot', 'IN', inputFilters.depots);
    grCust.query();

    while (grCust.next()) {
        var sId = grCust.getUniqueValue();
        sysIdArray.push(sId);
        masterRecords.push({
            sysId: sId,
            code: grCust.getValue('customer_code_sap'),
            name: grCust.getValue('customer_name'),
            pan: grCust.getValue('pan'),
            segment: grCust.getDisplayValue('segment'),
            zoneCode: grCust.getValue('zone'),
            zoneName: grCust.getValue('zone_name') || grCust.getValue('zone'),
            regionCode: grCust.getValue('region'),
            regionName: grCust.getValue('region_name') || grCust.getValue('region'),
            depotCode: grCust.getValue('depot'),
            depotName: grCust.getValue('depot_name') || grCust.getValue('depot')
        });
    }

    if (sysIdArray.length > 0) {
        var chunks = chunkArray(sysIdArray, 2000);
        for (var i = 0; i < chunks.length; i++) {
            var chunk = chunks[i];

            // REQUESTS
            var grReq = new GlideRecord(TABLES.request);
            grReq.addQuery('customer', 'IN', chunk);
            grReq.orderByDesc('sys_created_on');
            grReq.query();
            while (grReq.next()) {
                var cId = grReq.getValue('customer');
                if (!reqMap[cId]) {
                    reqMap[cId] = {
                        currentLimit: parseFloat(grReq.getValue('current_credit_limit')) || 0,
                        outstanding: parseFloat(grReq.getValue('outstanding_amount')) || 0,
                        grossExp: parseFloat(grReq.getValue('net_exposure')) || 0,
                        status: grReq.getDisplayValue('state') || 'Active',
                        stateRaw: (grReq.getValue('state') || '').toLowerCase(),
                        reviewDate: grReq.getValue('next_review_date'),
                        expectedPotential: parseFloat(grReq.getValue('u_tool_expected_potential')) || 0,
                        activeSd: parseFloat(grReq.getValue('active_sd')) || 0,
                        createdOn: grReq.getValue('sys_created_on') || ''
                    };
                }
            }

            // Snapshots
            var grSnap = new GlideRecord(TABLES.snapshot);
            grSnap.addQuery('customer', 'IN', chunk);
            grSnap.orderByDesc('sys_created_on');
            grSnap.query();
            while (grSnap.next()) {
                var cId2 = grSnap.getValue('customer');
                if (!snapMap[cId2]) {
                    snapMap[cId2] = {
                        outst: parseFloat(grSnap.getValue('total_outstanding')) || 0,
                        b0_21: parseFloat(grSnap.getValue('bucket_0_30_days')) || 0,
                        b22_30: parseFloat(grSnap.getValue('bucket_22_30_days')) || 0,
                        b31_45: parseFloat(grSnap.getValue('bucket_31_45_days')) || 0,
                        b46_60: parseFloat(grSnap.getValue('bucket_46_60_days')) || 0,
                        b61_75: parseFloat(grSnap.getValue('bucket_61_75_days')) || 0,
                        b76_90: parseFloat(grSnap.getValue('bucket_76_90_days')) || 0,
                        b91_120: parseFloat(grSnap.getValue('bucket_91_120_days')) || 0,
                        b121_180: parseFloat(grSnap.getValue('bucket_121_180_days')) || 0,
                        b181_365: parseFloat(grSnap.getValue('bucket_181_365_days')) || 0,
                        b366_730: parseFloat(grSnap.getValue('bucket_366_730_days')) || 0,
                        b730_above: parseFloat(grSnap.getValue('bucket_730_above')) || 0,
                        bGt120: parseFloat(grSnap.getValue('bucket_gt120_days')) || 0
                    };
                }
            }

            // Cumulative outstanding from Jan'26 (for OS/Sales)
            var gaOutSum = new GlideAggregate(TABLES.snapshot);
            gaOutSum.addQuery('customer', 'IN', chunk);
            gaOutSum.addQuery('snapshot_month', '>=', jan26Start);
            gaOutSum.addQuery('snapshot_month', '<=', jan26End);
            gaOutSum.addAggregate('SUM', 'total_outstanding');
            gaOutSum.groupBy('customer');
            gaOutSum.query();
            while (gaOutSum.next()) {
                var cId4 = gaOutSum.getValue('customer');
                if (!cId4) continue;
                outstandingSumMap[cId4] = parseFloat(gaOutSum.getAggregate('SUM', 'total_outstanding')) || 0;
            }

            // Sales data
            var grSales = new GlideRecord(TABLES.salesData);
            grSales.addQuery('u_customer', 'IN', chunk);
            grSales.query();
            while (grSales.next()) {
                var cId3 = grSales.getValue('u_customer');
                if (!cId3 || salesMap[cId3]) continue;
                var sum = 0, count = 0;
                for (var mIdx = 0; mIdx < SALES_FIELDS.length; mIdx++) {
                    var mv = parseFloat(grSales.getValue(SALES_FIELDS[mIdx]));
                    if (!isNaN(mv)) { sum += mv; count++; }
                }
                var avgMonthly = count > 0 ? (sum / count) : 0;
                var jan26Sum = 0;
                for (var jIdx = 0; jIdx < JAN26_SALES_FIELDS.length; jIdx++) {
                    var jv = parseFloat(grSales.getValue(JAN26_SALES_FIELDS[jIdx]));
                    if (!isNaN(jv)) jan26Sum += jv;
                }
                salesMap[cId3] = { avgMonthlySales: avgMonthly, salesFromJan26: jan26Sum };
            }
        }
    }

    // ==============================================
    // BUILD TABLE DATA
    // ==============================================
    var tableData = [];

    for (var j = 0; j < masterRecords.length; j++) {
        var cust = masterRecords[j];
        var req = reqMap[cust.sysId];
        if (!req) {
            req = { currentLimit: 0, outstanding: 0, grossExp: 0,
                    status: 'No Request', stateRaw: '', reviewDate: '', expectedPotential: 0,
                    activeSd: 0, createdOn: '' };
        }
        var snap = snapMap[cust.sysId] || { outst: 0, b0_21:0, b22_30:0, b31_45:0, b46_60:0,
                                             b61_75:0, b76_90:0, b91_120:0, b121_180:0,
                                             b181_365:0, b366_730:0, b730_above:0, bGt120:0 };
        var salesInfo = salesMap[cust.sysId] || { avgMonthlySales: 0, salesFromJan26: 0 };

        var custOutstanding = (req.status !== 'No Request') ? req.outstanding : snap.outst;

        var overdue_lt_60 = snap.b0_21 + snap.b22_30 + snap.b31_45 + snap.b46_60;
        var overdue_60_90 = snap.b61_75 + snap.b76_90;
        var overdue_gt_90 = snap.b91_120 + snap.b121_180 + snap.b181_365 + snap.b366_730 + snap.b730_above + snap.bGt120;
        var rowOverdue = overdue_lt_60 + overdue_60_90 + overdue_gt_90;

        var risk = 'No Overdue', riskClass = '';
        if (overdue_gt_90 > 0) { risk = 'High'; riskClass = 'clm-text-red'; }
        else if (overdue_60_90 > 0) { risk = 'Medium'; riskClass = 'clm-text-orange'; }
        else if (overdue_lt_60 > 0) { risk = 'Low'; riskClass = 'clm-text-green'; }

        var displayStatus = req.status;
        var cssClass = 'status-' + (req.status || 'norequest').toLowerCase().replace(/\s+/g, '-');
        var statLower = (req.status || '').toLowerCase();

        if (statLower.indexOf('submit') > -1 || statLower.indexOf('pend') > -1) {
            displayStatus = 'Pending'; cssClass = 'status-submitted';
        }

        var reviewDays = '--', reviewColor = '';
        if (req.reviewDate) {
            var diff = GlideDateTime.subtract(gdtToday, new GlideDateTime(req.reviewDate)).getRoundedDayPart();
            reviewDays = diff + 'd';
            reviewColor = diff <= 15 ? 'clm-text-red' : (diff <= 30 ? 'clm-text-orange' : 'clm-text-green');
        }

        var available = req.currentLimit - custOutstanding;
        var util = req.currentLimit > 0 ? Math.round((custOutstanding / req.currentLimit) * 100) : 0;
        var potential = req.expectedPotential || 0;
        var growthPct = potential > 0 ? (salesInfo.avgMonthlySales / potential) * 100 : 0;
        var highGrowth20 = growthPct > HIGH_GROWTH_THRESHOLD_PCT ? 'Yes' : 'No';
        var custOutstandingSum = outstandingSumMap[cust.sysId] || 0;
        var custSalesSum = salesInfo.salesFromJan26 || 0;
        var osSalesRatio = custSalesSum > 0 ? (custOutstandingSum / custSalesSum) : 0;

        tableData.push({
            sysId: cust.sysId,
            code: cust.code,
            name: cust.name,
            pan: cust.pan,
            segment: cust.segment,
            segmentClass: 'seg-' + (cust.segment || 'default').toLowerCase().replace(/\s+/g, '-'),
            zoneCode: cust.zoneCode,
            zoneName: cust.zoneName,
            regionCode: cust.regionCode,
            regionName: cust.regionName,
            depotCode: cust.depotCode,
            depotName: cust.depotName,
            status: displayStatus,
            statusClass: cssClass,
            outstanding: custOutstanding,
            limit: req.currentLimit,
            available: available,
            util: util,
            utilClass: util > 90 ? 'clm-text-red' : (util > 75 ? 'clm-text-orange' : 'clm-text-green'),
            od90: overdue_gt_90,
            risk: risk,
            riskClass: riskClass,
            reviewIn: reviewDays,
            reviewColor: reviewColor,
            avgMonthlySales: salesInfo.avgMonthlySales,
            highGrowthPct: growthPct,
            highGrowth20: highGrowth20,
            osSalesRatio: osSalesRatio,
            activeSd: req.activeSd || 0,
            overdueTotal: rowOverdue,
            grossExp: req.grossExp,
            createdOn: req.createdOn || ''
        });
    }

    data.tableData = tableData;

    // ============================================================
    // TREND, SALES, AGEING CHARTS (Fixed Last 6 Months)
    // ============================================================

    function buildTrendMonths(periodStr) {
        var out = [];
        var n = new Date();
        var cYr = n.getFullYear();
        var cMo = n.getMonth();
        for (var i = 5; i >= 0; i--) {
            var d6 = new Date(cYr, cMo - i, 1);
            out.push({ year: d6.getFullYear(), month: d6.getMonth() });
        }
        return out;
    }

    var sixMonths = buildTrendMonths('last_6_months');
    var snapStart = sixMonths[0].year + '-' + pad2(sixMonths[0].month + 1) + '-01 00:00:00';
    var snapLastDay = new Date(sixMonths[5].year, sixMonths[5].month + 1, 0).getDate();
    var snapEnd = sixMonths[5].year + '-' + pad2(sixMonths[5].month + 1) + '-' + pad2(snapLastDay) + ' 23:59:59';

    var outTrendAgg = {};
    var snapAggMap = {};
    var salesTrendMap = {};
    var volumeTrendMap = {};

    sixMonths.forEach(function(m) {
        var ym = m.year + '-' + pad2(m.month + 1);
        outTrendAgg[ym] = 0;
        snapAggMap[ym] = { b0_30:0, b22_30:0, b31_45:0, b46_60:0, b61_75:0, b76_90:0, b91_120:0, b121_180:0, b181_365:0, b366_730:0, b730_above:0 };
        salesTrendMap[ym] = 0;
        volumeTrendMap[ym] = 0;
    });

    if (sysIdArray.length > 0) {
        var chartChunks = chunkArray(sysIdArray, 2000);
        for (var cIdx = 0; cIdx < chartChunks.length; cIdx++) {
            var chk = chartChunks[cIdx];

            // 1. Snapshot Aggregates
            var gaSnap = new GlideAggregate(TABLES.snapshot);
            gaSnap.addQuery('customer', 'IN', chk);
            gaSnap.addQuery('snapshot_month', '>=', snapStart);
            gaSnap.addQuery('snapshot_month', '<=', snapEnd);
            gaSnap.addAggregate('SUM', 'total_outstanding');
            gaSnap.addAggregate('SUM', 'bucket_0_30_days');
            gaSnap.addAggregate('SUM', 'bucket_22_30_days');
            gaSnap.addAggregate('SUM', 'bucket_31_45_days');
            gaSnap.addAggregate('SUM', 'bucket_46_60_days');
            gaSnap.addAggregate('SUM', 'bucket_61_75_days');
            gaSnap.addAggregate('SUM', 'bucket_76_90_days');
            gaSnap.addAggregate('SUM', 'bucket_91_120_days');
            gaSnap.addAggregate('SUM', 'bucket_121_180_days');
            gaSnap.addAggregate('SUM', 'bucket_181_365_days');
            gaSnap.addAggregate('SUM', 'bucket_366_730_days');
            gaSnap.addAggregate('SUM', 'bucket_730_above');
            gaSnap.groupBy('snapshot_month');
            gaSnap.query();

            while (gaSnap.next()) {
                var sm = gaSnap.getValue('snapshot_month');
                if (!sm) continue;
                var ym = sm.substring(0, 7);
                if (outTrendAgg[ym] !== undefined) {
                    outTrendAgg[ym] += parseFloat(gaSnap.getAggregate('SUM', 'total_outstanding')) || 0;
                    snapAggMap[ym].b0_30 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_0_30_days')) || 0;
                    snapAggMap[ym].b22_30 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_22_30_days')) || 0;
                    snapAggMap[ym].b31_45 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_31_45_days')) || 0;
                    snapAggMap[ym].b46_60 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_46_60_days')) || 0;
                    snapAggMap[ym].b61_75 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_61_75_days')) || 0;
                    snapAggMap[ym].b76_90 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_76_90_days')) || 0;
                    snapAggMap[ym].b91_120 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_91_120_days')) || 0;
                    snapAggMap[ym].b121_180 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_121_180_days')) || 0;
                    snapAggMap[ym].b181_365 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_181_365_days')) || 0;
                    snapAggMap[ym].b366_730 += parseFloat(gaSnap.getAggregate('SUM', 'bucket_366_730_days')) || 0;
                    snapAggMap[ym].b730_above += parseFloat(gaSnap.getAggregate('SUM', 'bucket_730_above')) || 0;
                }
            }

            // 2. Sales Value
            var grSalesChart = new GlideRecord(TABLES.salesData);
            grSalesChart.addQuery('u_customer', 'IN', chk);
            grSalesChart.query();
            while (grSalesChart.next()) {
                sixMonths.forEach(function(m) {
                    var colName = 'u_' + MONTH_ABBR[m.month] + '_' + String(m.year).slice(-2);
                    if (grSalesChart.isValidField(colName)) {
                        var ymVal = m.year + '-' + pad2(m.month + 1);
                        salesTrendMap[ymVal] += parseFloat(grSalesChart.getValue(colName)) || 0;
                    }
                });
            }

            // 3. Sales Volume
            var grVolChart = new GlideRecord(TABLES.salesVol);
            grVolChart.addQuery('u_customer', 'IN', chk);
            grVolChart.query();
            while (grVolChart.next()) {
                sixMonths.forEach(function(m) {
                    var colName = 'u_' + MONTH_ABBR[m.month] + '_' + String(m.year).slice(-2);
                    if (grVolChart.isValidField(colName)) {
                        var ymVol = m.year + '-' + pad2(m.month + 1);
                        volumeTrendMap[ymVol] += parseFloat(grVolChart.getValue(colName)) || 0;
                    }
                });
            }
        }
    }

    var trendPoints = sixMonths.map(function(m) {
        var ym = m.year + '-' + pad2(m.month + 1);
        var label = MONTH_NAMES[m.month] + ' ' + String(m.year).slice(-2);
        return { label: label, value: outTrendAgg[ym] || 0, isFuture: false };
    });
    data.trend = { metric: 'outstanding', period: 'last_6_months', points: trendPoints };

    var salesPoints = [];
    var ageingData = [];

    for (var idx = 0; idx < sixMonths.length; idx++) {
        var mObj = sixMonths[idx];
        var ymKey = mObj.year + '-' + pad2(mObj.month + 1);
        var lbl = MONTH_NAMES[mObj.month] + ' ' + String(mObj.year).slice(-2);

        salesPoints.push({
            label: lbl,
            value: salesTrendMap[ymKey] || 0,     
            volume: volumeTrendMap[ymKey] || 0     
        });

        var sData = snapAggMap[ymKey];
        var combined_0_30 = sData.b0_30 + sData.b22_30;
        var combined_31_60 = sData.b31_45 + sData.b46_60;
        var combined_61_90 = sData.b61_75 + sData.b76_90;
        var combined_gt180 = sData.b181_365 + sData.b366_730 + sData.b730_above;

        ageingData.push({
            label: lbl,
            buckets: [
                { label: '0-30 Days', value: combined_0_30 },
                { label: '31-60 Days', value: combined_31_60 },
                { label: '61-90 Days', value: combined_61_90 },
                { label: '91-120 Days', value: sData.b91_120 },
                { label: '121-180 Days', value: sData.b121_180 },
                { label: '>180 Days', value: combined_gt180 }
            ]
        });
    }

    data.salesTrend = { metric: 'sales', points: salesPoints };
    data.ageingTrend = { months: ageingData };

})();
